// === Tab: mySketch ===
/***

A spiral network of alternating blue and gold nodes emerges from a dense central singularity. 
Local connections form transient pathways that ripple through the structure, 
creating the impression of information folding inward and expanding outward simultaneously. 
As the vortex rotates, the network continuously reorganizes itself, balancing order and turbulence between the core and the perimeter.

Drag to accelerate the flow of signals through the vortex. Press S to save an image.
***/

let nodes = [];
let t = 0;

const BLUE_H = 205;
const YELLOW_H = 48;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  background(230, 45, 4);
}

function draw() {
  background(230, 45, 4, 20);

  translate(width / 2, height / 2);
  rotate(t * 0.08);

  nodes = [];

  let turns = 9;
  let total = 360;
  let maxR = max(width, height) * 0.42;

  for (let i = 0; i < total; i++) {
    let p = i / total;
    let a = p * TWO_PI * turns;
    let r = pow(p, 0.75) * maxR;

    let wave = sin(a * 1.7 + t * 2.5) * 22;
    let pulse = sin(t * 3 + i * 0.08) * 8;

    let x = cos(a) * (r + wave);
    let y = sin(a) * (r + wave);

    let n = noise(i * 0.025, t * 0.4);
    x += cos(a + HALF_PI) * n * 35;
    y += sin(a + HALF_PI) * n * 35;

    let band = floor(p * 10);
    let hBand = band % 2 === 0 ? BLUE_H : YELLOW_H;

    let nodeSize =
        map(p, 0, 1, 1.5, 8.5) +
      map(pulse, -8, 8, 2.8, 4.8);

    nodes.push({
      x,
      y,
      r: nodeSize,
      h: hBand,
      p
    });
  }

  drawConnections();
  drawNodes();

  t += 0.01;
}

function drawConnections() {
  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      let d = dist(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);

      if (d < 55) {
        let sameColor = nodes[i].h === nodes[j].h;
        let h = sameColor ? nodes[i].h : (i % 2 === 0 ? BLUE_H : YELLOW_H);

        let alpha = map(d, 0, 55, 45, 0);
        let weight = map(d, 0, 55, 1.0, 0.1);

        stroke(h, 90, 100, alpha);
        strokeWeight(weight);
        line(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
      }
    }
  }
}

function drawNodes() {
  noStroke();

  for (let n of nodes) {
    fill(n.h, 90, 100, 4);
    circle(n.x, n.y, n.r * 2.8);

    fill(n.h, 90, 100, 28);
    circle(n.x, n.y, n.r);

    fill(n.h, 25, 100, 16);
    circle(n.x, n.y, n.r * 0.54);
  }
}

function mouseDragged() {
  t += 0.04;
}

function mousePressed() {
  background(230, 45, 4);
}

function keyPressed() {
  if (key === 's' || key === 'S') saveCanvas('neural-geometry-spiral', 'png');
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  background(230, 45, 4);
}

